    args: ['--no-sandbox', '--disable-setuid-sandbox'],
    headless: true,
  });
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => consoleErrors.push('pageerror: ' + err.message));

  await page.setViewport({ width: 1280, height: 720 });

  log('--- Navigating to movie list ---');
  await page.goto('http://localhost:4200/', { waitUntil: 'networkidle0' });
  await page.waitForSelector('[data-testid="day-picker"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 500));

  const bodyText1 = await page.evaluate(() => document.body.innerText.slice(0, 800));
  log('Body text after load:\n', bodyText1);

  await page.screenshot({ path: '/tmp/pw-test/1-movie-list.png' });

  // Try clicking a screening-button if present
  const hasScreeningButton = await page.$('[data-testid="screening-button"]');
  if (!hasScreeningButton) {
    log('No screening button found on today - trying day buttons to find a day with screenings');
    const dayButtons = await page.$$('[data-testid="day-button"]');
    for (let i = 0; i < dayButtons.length; i++) {
      await dayButtons[i].click();
      await new Promise((r) => setTimeout(r, 400));
      const found = await page.$('[data-testid="screening-button"]');
      if (found) {
        log(`Found screening on day-button index ${i}`);
        break;
      }
    }
  }

  const screeningBtn = await page.$('[data-testid="screening-button"]');
  if (!screeningBtn) {
    log('STILL no screening button found via day buttons, trying datepicker to navigate to 2026-09-15');
    await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle0' });
    await new Promise((r) => setTimeout(r, 500));
  }

  const screeningBtn2 = await page.$('[data-testid="screening-button"]');
  if (!screeningBtn2) {
    const bodyText2 = await page.evaluate(() => document.body.innerText.slice(0, 800));
    log('Still no screening button. Body:\n', bodyText2);
    await page.screenshot({ path: '/tmp/pw-test/1b-no-screenings.png' });
    throw new Error('Could not find a screening button to click');
  }

  log('--- Clicking screening button ---');
  await screeningBtn2.click();
  await page.waitForSelector('[data-testid="seat-map-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));
  await page.screenshot({ path: '/tmp/pw-test/2-seat-map.png', fullPage: true });

  const seatMapInfo = await page.evaluate(() => {
    const seats = document.querySelectorAll('[data-testid="seat"]').length;
    const couches = document.querySelectorAll('[data-testid="couch"]').length;
    const aisles = document.querySelectorAll('[data-testid="aisle"]').length;
    const unavailable = document.querySelectorAll('[data-testid="seat"][data-state="unavailable"], [data-testid="couch"][data-state="unavailable"]').length;
    const accessible = document.querySelectorAll('[data-testid="seat"][data-state="accessible"]').length;
    const subtitle = document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent;
    return { seats, couches, aisles, unavailable, accessible, subtitle };
  });
  log('Seat map info:', JSON.stringify(seatMapInfo));

  // select 2 regular available seats
  const availableSeats = await page.$$('[data-testid="seat"][data-state="available"]');
  log('Available seats found:', availableSeats.length);
  await availableSeats[0].click();
  await availableSeats[1].click();

  // select a couch
  const availableCouches = await page.$$('[data-testid="couch"][data-state="available"]');
  log('Available couches found:', availableCouches.length);
  await availableCouches[0].click();

  await new Promise((r) => setTimeout(r, 300));
  const panelText = await page.evaluate(() => document.querySelector('[data-testid="selected-seats"]')?.textContent);
  log('Selected-seats panel:', panelText);

  await page.screenshot({ path: '/tmp/pw-test/3-seats-selected.png', fullPage: true });

  log('--- Clicking Continue ---');
  await page.click('[data-testid="continue-button"]');
  await page.waitForSelector('[data-testid="summary-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));
  const summaryText = await page.evaluate(() => document.body.innerText);
  log('Summary page text:\n', summaryText);
  await page.screenshot({ path: '/tmp/pw-test/4-summary.png', fullPage: true });

  log('--- Clicking Confirm ---');
  await page.click('[data-testid="confirm-button"]');
  await page.waitForSelector('[data-testid="checkout-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));
  await page.screenshot({ path: '/tmp/pw-test/5-checkout-empty.png', fullPage: true });

  log('--- Clicking Pay with empty form (expect validation errors) ---');
  await page.click('[data-testid="pay-button"]');
  await new Promise((r) => setTimeout(r, 300));
  const errorsText = await page.evaluate(() => {
    const ids = ['first-name-error','last-name-error','email-error','confirm-email-error','phone-error','terms-error'];
    return ids.map(id => {
      const el = document.querySelector(`[data-testid="${id}"]`);
      return `${id}: ${el ? el.textContent : '(none)'}`;
    }).join('\n');
  });
  log('Validation errors after empty submit:\n', errorsText);
  const toastText = await page.evaluate(() => document.querySelector('[data-testid="toast"]')?.textContent);
  log('Toast:', toastText);
  await page.screenshot({ path: '/tmp/pw-test/6-checkout-errors.png', fullPage: true });

  log('--- Filling the form correctly ---');
  async function typeInto(testid, value) {
    const el = await page.$(`[data-testid="${testid}"]`);
    await el.click({ clickCount: 3 });
    await el.type(value);
