const puppeteer = require('puppeteer-core');

const log = (...args) => console.log(...args);
let failures = 0;
function check(label, cond) {
  if (cond) {
    log(`PASS: ${label}`);
  } else {
    log(`FAIL: ${label}`);
    failures++;
  }
}

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
    headless: true,
  });
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => consoleErrors.push('pageerror: ' + err.message));

  await page.setViewport({ width: 1280, height: 720 });

  const fakeNow = new Date('2026-09-15T10:00:00').getTime();
  await page.evaluateOnNewDocument((fakeNow) => {
    const OriginalDate = Date;
    const offset = fakeNow - OriginalDate.now();
    class FakeDate extends OriginalDate {
      constructor(...args) {
        if (args.length === 0) {
          super(OriginalDate.now() + offset);
        } else {
          super(...args);
        }
      }
      static now() {
        return OriginalDate.now() + offset;
      }
    }
    // eslint-disable-next-line no-global-assign
    Date = FakeDate;
  }, fakeNow);

  // ===== Test 1: route guards without a valid booking =====
  log('\n=== Test 1: route guards ===');
  await page.goto('http://localhost:4200/screenings/1/summary', { waitUntil: 'networkidle0' });
  await new Promise((r) => setTimeout(r, 400));
  check('summary without booking redirects to /', page.url() === 'http://localhost:4200/');

  await page.goto('http://localhost:4200/screenings/1/checkout', { waitUntil: 'networkidle0' });
  await new Promise((r) => setTimeout(r, 400));
  check('checkout without booking redirects to /', page.url() === 'http://localhost:4200/');

  await page.goto('http://localhost:4200/confirmation', { waitUntil: 'networkidle0' });
  await new Promise((r) => setTimeout(r, 400));
  check('confirmation without paid booking redirects to /', page.url() === 'http://localhost:4200/');

  // ===== Test 2: 10-seat cap + couch atomic select/deselect + Cancel =====
  log('\n=== Test 2: seat cap, couch atomicity, cancel ===');
  await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle0' });
  await page.waitForSelector('[data-testid="screening-button"]', { timeout: 10000 });
  await page.click('[data-testid="screening-button"]');
  await page.waitForSelector('[data-testid="seat-map-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));

  // select 10 regular available seats one at a time, then try an 11th
  let available = await page.$$('[data-testid="seat"][data-state="available"]');
  for (let i = 0; i < 10; i++) {
    const seats = await page.$$('[data-testid="seat"][data-state="available"]');
    await seats[0].click();
    await new Promise((r) => setTimeout(r, 50));
  }
  let count = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  log('Count after 10 selections:', count);
  check('selected-seats-count shows 10', count === 'Selected seats: 10');

  // try selecting an 11th seat - should be blocked with toast
  const seatsAfter10 = await page.$$('[data-testid="seat"][data-state="available"]');
  await seatsAfter10[0].click();
  await new Promise((r) => setTimeout(r, 300));
  const toastAfterCap = await page.evaluate(() => document.querySelector('[data-testid="toast"]')?.textContent);
  log('Toast after exceeding cap:', toastAfterCap);
  check('toast shown for exceeding cap', toastAfterCap === 'Maximum 10 seats per booking');
  const countAfterCapAttempt = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  check('count still 10 after blocked attempt', countAfterCapAttempt === 'Selected seats: 10');

  // deselect one seat to free capacity, then try a couch (worth 2) - should work since we'd be at 9+2=11... wait need at 8 first
  // deselect 3 seats to get to 7, then couch (2) -> 9, fine. Then another couch -> 11 should be blocked (couch is atomic so neither seat added)
  const selectedSeats = await page.$$('[data-testid="seat"][data-state="selected"]');
  for (let i = 0; i < 3; i++) {
    await selectedSeats[i].click();
    await new Promise((r) => setTimeout(r, 50));
  }
  let countAfterDeselect = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  check('count is 7 after deselecting 3', countAfterDeselect === 'Selected seats: 7');

  const couches1 = await page.$$('[data-testid="couch"][data-state="available"]');
  await couches1[0].click();
  await new Promise((r) => setTimeout(r, 200));
  let countAfterCouch = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  check('count is 9 after adding couch (2 seats)', countAfterCouch === 'Selected seats: 9');

  // couch atomicity: the couch should show as fully selected (data-state=selected), not half
  const couchState = await page.evaluate(() => document.querySelectorAll('[data-testid="couch"][data-state="selected"]').length);
  check('exactly 1 couch shows as fully selected', couchState === 1);

  // now try another couch (would bring to 11) - should be blocked atomically (couch never partially added)
  const couches2 = await page.$$('[data-testid="couch"][data-state="available"]');
  await couches2[0].click();
  await new Promise((r) => setTimeout(r, 300));
  const toastAfterCouchCap = await page.evaluate(() => document.querySelector('[data-testid="toast"]')?.textContent);
  check('toast shown for couch exceeding cap', toastAfterCouchCap === 'Maximum 10 seats per booking');
  const countAfterCouchCapAttempt = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  check('count still 9 after blocked couch attempt (atomic)', countAfterCouchCapAttempt === 'Selected seats: 9');

  // deselect the selected couch - should remove both seats atomically
  const selectedCouch = await page.$('[data-testid="couch"][data-state="selected"]');
  await selectedCouch.click();
  await new Promise((r) => setTimeout(r, 200));
  const countAfterCouchDeselect = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
  check('count is 7 after deselecting couch (atomic -2)', countAfterCouchDeselect === 'Selected seats: 7');

  // click an unavailable seat - should be a no-op
  const unavailableSeat = await page.$('[data-testid="seat"][data-state="unavailable"]');
  if (unavailableSeat) {
    await unavailableSeat.click();
    await new Promise((r) => setTimeout(r, 200));
    const countAfterUnavailClick = await page.evaluate(() => document.querySelector('[data-testid="selected-seats-count"]')?.textContent);
    check('clicking unavailable seat is a no-op', countAfterUnavailClick === 'Selected seats: 7');
  } else {
    log('No unavailable seat found to test no-op click');
  }

  // Cancel button - should clear booking and go home
  await page.click('[data-testid="cancel-button"]');
  await new Promise((r) => setTimeout(r, 400));
  check('cancel navigates to /', page.url().startsWith('http://localhost:4200/') && !page.url().includes('/screenings/'));
  const bookingAfterCancel = await page.evaluate(() => sessionStorage.getItem('cinescope:booking'));
  log('Booking in sessionStorage after cancel:', bookingAfterCancel);
  check('booking cleared from sessionStorage after cancel', bookingAfterCancel === null);

  // ===== Test 3: Back navigation persistence (seat map -> summary -> back) =====
  log('\n=== Test 3: Back navigation persistence ===');
  await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle0' });
  await page.waitForSelector('[data-testid="screening-button"]', { timeout: 10000 });
  await page.click('[data-testid="screening-button"]');
  await page.waitForSelector('[data-testid="seat-map-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));

  const avail2 = await page.$$('[data-testid="seat"][data-state="available"]');
  await avail2[0].click();
  await avail2[1].click();
  await new Promise((r) => setTimeout(r, 200));
  const seatIdsSelected = await page.evaluate(() =>
    Array.from(document.querySelectorAll('[data-testid="seat"][data-state="selected"]')).map(
      (el) => `${el.getAttribute('data-row')}-${el.getAttribute('data-column')}`,
    ),
  );
  log('Selected seat ids before navigating to summary:', seatIdsSelected);

  await page.click('[data-testid="continue-button"]');
  await page.waitForSelector('[data-testid="summary-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));

  await page.click('[data-testid="back-button"]');
  await page.waitForSelector('[data-testid="seat-map-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));
  const seatIdsAfterBack = await page.evaluate(() =>
    Array.from(document.querySelectorAll('[data-testid="seat"][data-state="selected"]')).map(
      (el) => `${el.getAttribute('data-row')}-${el.getAttribute('data-column')}`,
    ),
  );
  log('Selected seat ids after Back from summary:', seatIdsAfterBack);
  check(
    'selection persists after Back from summary',
    JSON.stringify(seatIdsSelected.sort()) === JSON.stringify(seatIdsAfterBack.sort()),
  );

  // go forward to summary, then checkout, then back to summary, then back to seatmap, verify persistence + reload
  await page.click('[data-testid="continue-button"]');
  await page.waitForSelector('[data-testid="summary-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 200));
  await page.click('[data-testid="confirm-button"]');
  await page.waitForSelector('[data-testid="checkout-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 200));

  // fill a bit of the form, go back to summary, confirm form value persists when returning to checkout
  await page.click('[data-testid="first-name-input"]', { clickCount: 3 });
  await page.type('[data-testid="first-name-input"]', 'Persisted');
  await new Promise((r) => setTimeout(r, 100));

  await page.click('[data-testid="back-button"]');
  await page.waitForSelector('[data-testid="summary-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 200));
  await page.click('[data-testid="confirm-button"]');
  await page.waitForSelector('[data-testid="checkout-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 200));
  const firstNameValue = await page.evaluate(() => document.querySelector('[data-testid="first-name-input"]')?.value);
  check('first name persists across checkout -> summary -> checkout', firstNameValue === 'Persisted');

  // reload on checkout, confirm persistence across reload
  await page.reload({ waitUntil: 'networkidle0' });
  await page.waitForSelector('[data-testid="checkout-title"]', { timeout: 10000 });
  await new Promise((r) => setTimeout(r, 300));
  const firstNameAfterReload = await page.evaluate(() => document.querySelector('[data-testid="first-name-input"]')?.value);
  check('first name persists after reload', firstNameAfterReload === 'Persisted');

  // ===== Test 4: email/phone validation edge cases =====
  log('\n=== Test 4: validation edge cases ===');
  async function setVal(testid, value) {
    const el = await page.$(`[data-testid="${testid}"]`);
    await el.click({ clickCount: 3 });
    await page.keyboard.press('Backspace');
    if (value) await el.type(value);
    await page.keyboard.press('Tab');
  }

  await setVal('email-input', 'not-an-email');
  await new Promise((r) => setTimeout(r, 150));
  let emailErr = await page.evaluate(() => document.querySelector('[data-testid="email-error"]')?.textContent);
  check('invalid email "not-an-email" shows error', emailErr === 'Enter a valid email address');

  await setVal('email-input', 'a@b');
  await new Promise((r) => setTimeout(r, 150));
  emailErr = await page.evaluate(() => document.querySelector('[data-testid="email-error"]')?.textContent);
  check('invalid email "a@b" shows error', emailErr === 'Enter a valid email address');

  await setVal('email-input', 'a@b.com');
  await new Promise((r) => setTimeout(r, 150));
  emailErr = await page.evaluate(() => document.querySelector('[data-testid="email-error"]')?.textContent);
  check('valid email "a@b.com" shows no error', !emailErr);

  await setVal('confirm-email-input', 'different@b.com');
  await new Promise((r) => setTimeout(r, 150));
  let confirmErr = await page.evaluate(() => document.querySelector('[data-testid="confirm-email-error"]')?.textContent);
  check('mismatched confirm email shows error', confirmErr === 'Email addresses do not match');

  // now change email after confirm-email was touched - confirm error should re-evaluate
  await setVal('email-input', 'different@b.com');
  await new Promise((r) => setTimeout(r, 150));
  confirmErr = await page.evaluate(() => document.querySelector('[data-testid="confirm-email-error"]')?.textContent);
  check('confirm-email error clears when email changed to match', !confirmErr);

  await setVal('phone-input', '12345');
  await new Promise((r) => setTimeout(r, 150));
  let phoneErr = await page.evaluate(() => document.querySelector('[data-testid="phone-error"]')?.textContent);
  check('5-digit phone shows error', phoneErr === 'Phone number must be exactly 9 digits');

  await setVal('phone-input', '12a456789');
  await new Promise((r) => setTimeout(r, 150));
  phoneErr = await page.evaluate(() => document.querySelector('[data-testid="phone-error"]')?.textContent);
  check('non-digit phone shows error', phoneErr === 'Phone number must be exactly 9 digits');

  await setVal('phone-input', '');
  await new Promise((r) => setTimeout(r, 150));
  phoneErr = await page.evaluate(() => document.querySelector('[data-testid="phone-error"]')?.textContent);
  check('empty phone (optional) shows no error', !phoneErr);

  await setVal('last-name-input', 'A');
  await new Promise((r) => setTimeout(r, 150));
  let lastNameErr = await page.evaluate(() => document.querySelector('[data-testid="last-name-error"]')?.textContent);
  check('1-char last name shows error', lastNameErr === 'Last name must be at least 2 characters');

  log('\n=== Console errors collected ===');
  log(consoleErrors.length ? consoleErrors.join('\n') : '(none)');

  log(`\n=== RESULT: ${failures === 0 ? 'ALL PASSED' : failures + ' FAILURES'} ===`);

  await browser.close();
  process.exit(failures === 0 ? 0 : 1);
})().catch((e) => {
  console.error('TEST SCRIPT ERROR:', e);
  process.exit(1);
});

